const movementKeys=new Set();
let movementFrame=null,lastMovementTime=0;
function moveCameraFrame(time){if(!movementKeys.size){movementFrame=null;lastMovementTime=0;return}const elapsed=lastMovementTime?Math.min((time-lastMovementTime)/1000,.05):0;lastMovementTime=time;const forward=new THREE.Vector3(),right=new THREE.Vector3(),offset=new THREE.Vector3();camera.getWorldDirection(forward);forward.y=0;if(forward.lengthSq()>0)forward.normalize();right.set(-forward.z,0,forward.x);if(movementKeys.has('w'))offset.add(forward);if(movementKeys.has('s'))offset.sub(forward);if(movementKeys.has('d'))offset.add(right);if(movementKeys.has('a'))offset.sub(right);if(movementKeys.has(' '))offset.y+=1;if(movementKeys.has('shift'))offset.y-=1;if(offset.lengthSq()>0){offset.normalize().multiplyScalar((movementKeys.has('control')?24:8)*elapsed);camera.position.add(offset);orbit.target.add(offset);orbit.update();renderer.render(scene,camera)}movementFrame=requestAnimationFrame(moveCameraFrame)}
