let state={kind:'entity',name:'Untitled_Model',height:1.8,parts:[],textures:[]}, selectedId=null, meshes=new Map(), tool='select', placingVoxel=false, snapshotBeforeEdit=null, undoStack=[],redoStack=[],toastTimer;
