function setDefaults(){state.parts=state.kind==='entity'?[makePart('body','teal',[0,.7,0],[.7,1.15,.42]),makePart('head','skin',[0,1.55,0],[.42,.42,.42])]:[makePart('stone_base','stone',[0,.25,0],[2,.5,2])];state.textures=[];for(const part of state.parts)ensurePartTexture(part);state.parts[0].solid=true;selectedId=state.parts[0].id}
