function syncScene(){for(const mesh of meshes.values()){scene.remove(mesh);mesh.geometry.dispose();for(const material of Array.isArray(mesh.material)?mesh.material:[mesh.material]){if(material.map&&!Array.from(pixelTextureCache.values()).some(cached=>cached.texture===material.map))material.map.dispose();material.dispose()}}meshes.clear();for(const part of state.parts){ensurePartTexture(part);let materials;if(state.kind==='entity'){materials=geometryFaces.map(face=>{const mapping=part.faces?.[face.name],textureId=mapping?.textureId||part.defaultTexture;const textureData=pixelTexture(textureId);const map=textureData?canvasTexture(textureData):null;return new THREE.MeshLambertMaterial({color:0xffffff,map,vertexColors:true,alphaTest:128/255,side:THREE.DoubleSide})});const geometry=createPreviewGeometry();const uv=geometry.getAttribute('uv');let cursor=0;for(const face of geometryFaces){const mapping=part.faces?.[face.name];for(let i=0;i<4;i++){const transformed=transformUv(face.uv[i],mapping);uv.setXY(cursor++,transformed[0],transformed[1])}}uv.needsUpdate=true;const mesh=new THREE.Mesh(geometry,materials);mesh.position.set(part.x,part.y,part.z);mesh.scale.set(part.w,part.h,part.d);mesh.rotation.y=THREE.MathUtils.degToRad(part.yaw);mesh.userData.faceTextureIds=geometryFaces.map(face=>part.faces?.[face.name]?.textureId||part.defaultTexture);mesh.userData.partId=part.id;scene.add(mesh);meshes.set(part.id,mesh);continue}else{const source=worldTexture(part.material),map=source.clone();map.needsUpdate=true;map.repeat.set(Math.max(.01,part.w/1.6),Math.max(.01,part.h/1.6));materials=new THREE.MeshLambertMaterial({color:colorFor(part.material),map})}const mesh=new THREE.Mesh(boxGeometry,materials);mesh.position.set(part.x,part.y,part.z);mesh.scale.set(part.w,part.h,part.d);mesh.rotation.y=THREE.MathUtils.degToRad(part.yaw);mesh.userData.partId=part.id;scene.add(mesh);meshes.set(part.id,mesh)}selectPart(selectedId);updateOutliner();requestRender()}
