function updateFaceMapping(){const part=state.parts.find(item=>item.id===selectedId);if(!part)return;const textureId=$('faceTexture').value;if(!textureId)return;checkpoint();if(!part.faces)part.faces={};const mapping={textureId,rotation:Number($('faceRotation').value),mirrorU:$('mirrorU').checked,mirrorV:$('mirrorV').checked};if(textureId===part.defaultTexture&&!mapping.rotation&&!mapping.mirrorU&&!mapping.mirrorV)delete part.faces[selectedFace];else part.faces[selectedFace]=mapping;selectedTextureId=textureId;syncScene();renderTextureWorkspace()}
