function applyPaint(event){const texture=pixelTexture(selectedTextureId);if(!texture||!selectedPaletteSymbol)return;if(paintTool==='erase'&&!texture.eraseSymbol){if(event.type==='pointerdown')showToast('No free palette index for transparency');return}const point=canvasPixel(event);if(!point)return;const [x,y]=point;if(paintTool==='eyedropper'){const symbol=texture.pixels[y][x];selectedPaletteSymbol=symbol;openPaletteEditor(symbol);renderPixelPalette();setPaintTool('pencil');return}if(paintTool==='fill'){if(event.type!=='pointerdown')return;checkpoint();fillPixels(texture,x,y,selectedPaletteSymbol);syncTexturePreview(texture);renderPixelCanvas();return}if(paintTool==='pencil'||paintTool==='erase'){if(event.type==='pointerdown'){checkpoint();painting=true;paintStart=point}if(!painting)return;const previous=paintStart||point;paintLine(texture,previous[0],previous[1],x,y,paintTool==='erase'?texture.eraseSymbol:selectedPaletteSymbol);paintStart=point;paintChanged=true;syncTexturePreview(texture);renderPixelCanvas()}}
