function finishPaint(event){if(!paintStart||!['line','rectangle'].includes(paintTool)){paintStart=null;return}const texture=pixelTexture(selectedTextureId),end=canvasPixel(event);if(!texture||!end)return;const [x0,y0]=paintStart,[x1,y1]=end,symbol=selectedPaletteSymbol;if(paintTool==='line')paintLine(texture,x0,y0,x1,y1,symbol);else for(let y=Math.min(y0,y1);y<=Math.max(y0,y1);y++)for(let x=Math.min(x0,x1);x<=Math.max(x0,x1);x++)if(x===Math.min(x0,x1)||x===Math.max(x0,x1)||y===Math.min(y0,y1)||y===Math.max(y0,y1))setCanvasPixel(texture,x,y,symbol);syncTexturePreview(texture);renderPixelCanvas();paintStart=null;paintChanged=true}
function updateOutliner(){const list=$('partList'),query=$('partSearch').value.trim().toLowerCase();list.innerHTML='';const visibleParts=state.parts.filter(part=>!query||part.id.toLowerCase().includes(query)||part.material.toLowerCase().includes(query));visibleParts.forEach(part=>{const row=document.createElement('div');row.className='part-row'+(part.id===selectedId?' selected':'');row.dataset.id=part.id;row.innerHTML='<span class="part-icon">▧</span><span class="part-name"></span><span class="part-material"></span>';row.querySelector('.part-name').textContent=part.id;row.querySelector('.part-material').title=part.material;row.querySelector('.part-material').style.background=colorFor(part.material);row.addEventListener('click',()=>selectPart(part.id));list.append(row)});$('partCount').textContent=query?`${visibleParts.length}/${state.parts.length}`:String(state.parts.length).padStart(2,'0');$('sceneStatus').textContent=`${state.parts.length} ${state.parts.length===1?'part':'parts'} · ${state.kind==='entity'?'model':'structure'}`}
function selectPart(id){selectedId=id;const part=state.parts.find(p=>p.id===id);const mesh=meshes.get(id),textureTab=currentInspectorTab==='textures';if(mesh)gizmo.attach(mesh);else gizmo.detach();$('emptyInspector').hidden=textureTab||!!part;$('inspectorContent').hidden=textureTab||!part;$('modelProperties').hidden=textureTab||state.kind!=='entity';$('selectionReadout').textContent=part?`${part.id}  ·  ${part.w.toFixed(2)} × ${part.h.toFixed(2)} × ${part.d.toFixed(2)}`:'No selection';updateOutliner();if(!part){renderTextureWorkspace();return}selectedTextureId=part.faces?.[selectedFace]?.textureId||part.defaultTexture||null;$('partId').value=part.id;$('posX').value=part.x;$('posY').value=part.y;$('posZ').value=part.z;$('sizeX').value=part.w;$('sizeY').value=part.h;$('sizeZ').value=part.d;$('yaw').value=part.yaw;$('material').value=part.material;$('partType').textContent=state.kind==='entity'?'ENTITY PART':'STRUCTURE CUBOID';$('solid').checked=part.solid;$('hasInteraction').checked=!!part.interaction;$('interactionFields').hidden=!part.interaction;if(part.interaction){$('interactionType').value=part.interaction.type;$('interactionTitle').value=part.interaction.title;$('interactionMessage').value=part.interaction.message}document.querySelectorAll('.swatch').forEach(button=>button.classList.toggle('chosen',button.dataset.material===part.material));renderTextureWorkspace()}
function selectFromCanvas(event){const rect=renderer.domElement.getBoundingClientRect();pointer.x=((event.clientX-rect.left)/rect.width)*2-1;pointer.y=-((event.clientY-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects([...meshes.values()]);if(hits.length){selectPart(hits[0].object.userData.partId);return true}return false}
