let pointerStart=null;renderer.domElement.addEventListener('pointerdown',event=>{pointerStart={x:event.clientX,y:event.clientY,button:event.button}});renderer.domElement.addEventListener('pointerup',event=>{if(!pointerStart)return;const moved=Math.hypot(event.clientX-pointerStart.x,event.clientY-pointerStart.y);if(pointerStart.button===0&&moved<4&&!gizmo.dragging){if(placingVoxel){const rect=renderer.domElement.getBoundingClientRect();pointer.set(((event.clientX-rect.left)/rect.width)*2-1,-((event.clientY-rect.top)/rect.height)*2+1);raycaster.setFromCamera(pointer,camera);if(raycaster.ray.intersectPlane(groundPlane,hitPoint)){const unit=1;const x=Math.round(hitPoint.x/unit)*unit,z=Math.round(hitPoint.z/unit)*unit;addPart(true,[x,.5,z])}}else selectFromCanvas(event)}pointerStart=null});
