function frameBounds(bounds){if(bounds.isEmpty())return;const center=bounds.getCenter(new THREE.Vector3()),size=bounds.getSize(new THREE.Vector3()),radius=Math.max(size.length()*.5,.5),distance=radius/Math.sin(THREE.MathUtils.degToRad(camera.fov*.5))*1.18,direction=camera.position.clone().sub(orbit.target);if(direction.lengthSq()<1e-6)direction.set(1,.8,1);direction.normalize();orbit.target.copy(center);camera.position.copy(center).addScaledVector(direction,distance);camera.near=Math.max(.01,distance/1000);camera.far=Math.max(500,distance+radius*4);camera.updateProjectionMatrix();orbit.minDistance=Math.max(.1,radius*.015);orbit.maxDistance=Math.max(500,distance*8);const gridScale=Math.max(1,Math.max(size.x,size.z)/24*1.25);grid.scale.set(gridScale,1,gridScale);orbit.update()}
