window.addEventListener('keydown',event=>{const target=event.target;if(target instanceof Element&&target.matches('input,select,textarea,[contenteditable="true"]'))return;const key=event.key===' '? ' ':event.key.toLowerCase();if(['w','a','s','d',' ','shift','control'].includes(key)&&!gizmo.dragging&&!painting){if(key===' ')event.preventDefault();startCameraMovement(key);return}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo();return}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();redo();return}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='d'){event.preventDefault();duplicatePart();return}if(event.key==='Delete'||event.key==='Backspace'){deletePart();return}if(currentInspectorTab==='textures'){const paintKeys={b:'pencil',e:'erase',g:'fill',i:'eyedropper',l:'line',u:'rectangle'};if(paintKeys[event.key.toLowerCase()]){setPaintTool(paintKeys[event.key.toLowerCase()]);return}}const keys={q:'select',w:'move',e:'rotate',r:'scale'};if(keys[event.key.toLowerCase()])setTool(keys[event.key.toLowerCase()]);if(event.key.toLowerCase()==='f')frameSelection();if(event.key==='Home'){event.preventDefault();frameScene()}});
